def _contact_truth_wrapper(low, contact_move, log_path):
    """Runner-side ground truth for scoring only: MuJoCo contact pairs at the end of every contact_move (parent, unchanged)."""
    import json as _json
    import time as _time

    def truth_snapshot():
        try:
            sim = low.handle.env.sim; m = sim.model; raw_m = getattr(m, "_model", None); raw_d = getattr(sim.data, "_data", None)
            task_env = low.handle.env.env; obj_bodies = {b: n for n, b in dict(task_env.obj_body_id).items()}
            pairs = []
            for i in range(int(raw_d.ncon)):
                c = raw_d.contact[i]; b1 = int(raw_m.geom_bodyid[c.geom1]); b2 = int(raw_m.geom_bodyid[c.geom2])
                n1 = m.body_id2name(b1); n2 = m.body_id2name(b2)
                robot1 = n1.startswith(("robot0", "gripper0")); robot2 = n2.startswith(("robot0", "gripper0"))
                obj1 = obj_bodies.get(b1); obj2 = obj_bodies.get(b2)
                if robot1 or robot2 or obj1 or obj2:
                    pairs.append({"b1": n1, "b2": n2, "dist": round(float(c.dist), 5), "robot_involved": bool(robot1 or robot2), "object_involved": bool(obj1 or obj2)})
            held = [n for n, b in dict(task_env.obj_body_id).items() if any((p["b1"].startswith("gripper0") and p["b2"] == m.body_id2name(b)) or (p["b2"].startswith("gripper0") and p["b1"] == m.body_id2name(b)) for p in pairs)]
            obj_nonrobot = [p for p in pairs if p["object_involved"] and not p["robot_involved"]]
            finger_nonobject = [p for p in pairs if p["robot_involved"] and not p["object_involved"] and (p["b1"].startswith("gripper0") or p["b2"].startswith("gripper0"))]
            return {"ncon_relevant": len(pairs), "pairs": pairs[:40], "objects_touching_gripper": held, "object_nonrobot_contacts": obj_nonrobot[:20], "gripper_nonobject_contacts": finger_nonobject[:20]}
        except Exception as e:  # noqa: BLE001
            return {"error": repr(e)}

    def wrapped(*args, **kwargs):
        res = contact_move(*args, **kwargs)
        try:
            r = res if isinstance(res, dict) else {}
            rec = {"t": round(_time.time(), 3), "sim_step": int(low._sim_step_count), "label": r.get("label", kwargs.get("label")), "status": r.get("status"), "detail": r.get("detail"), "success": r.get("success"), "truth": truth_snapshot()}
            with open(log_path, "a") as f:
                f.write(_json.dumps(rec, default=str) + "\n")
        except Exception as e:  # noqa: BLE001
            with open(log_path, "a") as f:
                f.write(_json.dumps({"error": repr(e)}) + "\n")
        return res
    return wrapped


def calibration_truth(env):
    """Runner-only: ray-cast tops of all objects (grid), table top under each object; public base frame (parent, unchanged)."""
    import mujoco
    low = env.low_level_env; sim = low.handle.env.sim; m = sim.model; task_env = low.handle.env.env
    base_p = sim.data.xpos[m.body_name2id("robot0_base")].copy(); raw_m = getattr(m, "_model", None); raw_d = getattr(sim.data, "_data", None)
    body_names = [m.body_id2name(i) for i in range(m.nbody)]; obj_ids = dict(task_env.obj_body_id); out = {"base_pos_world": base_p.tolist(), "objects": {}}

    def ray_down(xy, z_from=0.6):
        pnt = np.array([xy[0] + base_p[0], xy[1] + base_p[1], z_from + base_p[2]], float); gid = np.array([-1], np.int32)
        dist = mujoco.mj_ray(raw_m, raw_d, pnt, np.array([0.0, 0.0, -1.0]), None, 1, -1, gid)
        return (None, None) if dist < 0 else (float(z_from - dist), body_names[int(m.geom_bodyid[int(gid[0])])])

    for n, bid in obj_ids.items():
        p = (sim.data.xpos[bid] - base_p); hits = []
        for dx in np.arange(-0.06, 0.0601, 0.01):
            for dy in np.arange(-0.06, 0.0601, 0.01):
                z, b = ray_down(p[:2] + [dx, dy])
                if z is not None and b is not None and (b == body_names[bid] or b.startswith(n)):
                    hits.append((z, round(float(dx), 3), round(float(dy), 3)))
        tz = None
        for r in (0.10, 0.14):
            z, b = ray_down(p[:2] + [0.0, r])
            if z is not None and not (b == body_names[bid] or b.startswith(n)):
                tz = z; break
        out["objects"][n] = {"origin_public": p.round(4).tolist(), "top_z": max(hits)[0] if hits else None, "n_hits": len(hits), "footprint_halfwidth_x": (max(h[1] for h in hits) - min(h[1] for h in hits)) / 2 if hits else None,
                             "footprint_halfwidth_y": (max(h[2] for h in hits) - min(h[2] for h in hits)) / 2 if hits else None, "table_top_z_near": tz}
    return out


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--arm", required=True, choices=list(ARM_BASE)); p.add_argument("--suite", required=True); p.add_argument("--task", required=True); p.add_argument("--seed", required=True, type=int)
    p.add_argument("--code", required=True, type=Path); p.add_argument("--outdir", required=True, type=Path); p.add_argument("--phase", default="dev"); p.add_argument("--uid", required=True)
    a = p.parse_args()
    short = SHORT.get((a.suite, a.task), a.task[:24])
    out = a.outdir / a.arm / short / f"seed_{a.seed:02d}"; out.mkdir(parents=True, exist_ok=True)
    code_bytes = a.code.read_bytes(); code_sha = hashlib.sha256(code_bytes).hexdigest(); (out / "policy.py").write_bytes(code_bytes)
    marker = PROGRAM_MARKER.get(a.arm)
    if marker is not None:
        assert marker in code_bytes.decode("utf-8", "ignore"), f"program/arm mismatch: {a.arm} program must contain {marker!r}"
    attempt_id = f"{a.arm}:{short}:s{a.seed:02d}:{a.uid}"
    if a.suite == "rsi_source_synthetic":
        from register_synthetic import register_synthetic
        register_synthetic(MANIFEST, Path(os.environ["EXPERIMENT_DIR"]))
    t_env0 = time.time(); task_id = rt._find_task_id(a.suite, a.task)
    config = copy.deepcopy(yaml.safe_load((RECURSIA_SIM_ROOT / "env_configs/libero/franka_libero_libero10_traced.yaml").read_text()))
    config["env"]["cfg"]["low_level"] = {"_target_": "cap.envs.simulators.libero.FrankaLiberoEnv", "suite_name": a.suite, "task_id": task_id, "privileged": config.get("env", {}).get("cfg", {}).get("privileged", False),
                                          "max_steps": 4000, "seed": None, "enable_render": False, "viser_debug": False}
    config["trials"] = 1; config["output_dir"] = str(out / "artifacts")
    env = instantiate(config["env"]); obs, info = env.reset(seed=a.seed)
    n_states = len(env.low_level_env.handle.init_states); state_idx = (a.seed - 1) % n_states; env_setup_s = time.time() - t_env0
    (out / "diag").mkdir(exist_ok=True)
    try:
        (out / "diag" / "calibration_truth.json").write_text(json.dumps(calibration_truth(env), indent=1))
    except Exception as e:  # noqa: BLE001
        (out / "diag" / "calibration_truth.json").write_text(json.dumps({"error": repr(e)}))
    runtime_language = str(env.low_level_env.handle.task_language)
    descriptors = descriptors_for(runtime_language)
    descriptor_sha = hashlib.sha256(json.dumps(descriptors, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    adapter_files = {name: hashlib.sha256((HERE / name).read_bytes()).hexdigest() for name in ("adapter_v3.py", "adapter_lexicon_v3.json")}
    (out / "diag" / "task_descriptors.json").write_text(json.dumps(descriptors, indent=1))
    mi, cp, gate, pg, home_stats = install_interface(env, a.arm, out / "diag", descriptors)
    rec = DiagRecorder2(env, out / "diag"); rec.install_api_wrappers(); rec.install_step_sampler(); rec.snapshot("episode_start")
    horizon_guard = HorizonGuard(env.low_level_env)
    blocks = rt._parse_code_blocks(str(a.code)); t0 = time.time(); reward = 0.0; terminated = truncated = False; info_step = {}
    for i, code in enumerate(blocks):
        obs, reward, terminated, truncated, info_step = env.step(horizon_guard.block(code, env._exec_globals))
        if horizon_guard.exhausted:
            assert info_step.get("sandbox_rc") == 0, "A real error must not be masked as a timeout"
            reward = 0.0; terminated = False; truncated = True
            info_step["task_completed"] = False
            info_step["failure_class"] = "episode_timeout"
        if terminated or truncated:
            break
    duration = time.time() - t0
    final = rec.snapshot("policy_complete", extra={"info_step_task_completed": info_step.get("task_completed"), "sandbox_rc": info_step.get("sandbox_rc"), "reward": reward, "terminated": terminated, "truncated": truncated})
    tc = int(bool(info_step.get("task_completed"))); src = int(info_step.get("sandbox_rc", 0)); reward = float(reward)
    trial_dir = out / "artifacts" / f"trial_{a.seed:02d}_sandboxrc_{src}_reward_{reward:.3f}_taskcompleted_{tc}"; trial_dir.mkdir(parents=True, exist_ok=True)
    (trial_dir / "code.py").write_text("\n\n".join(f"# Code block {i}\n{b}" for i, b in enumerate(blocks)))
    (trial_dir / "stdout.txt").write_text(info_step.get("stdout", "")); (trial_dir / "stderr.txt").write_text(info_step.get("stderr", ""))
    for api in env._apis.values():
        if hasattr(api, "get_trace_logger"):
            api.get_trace_logger().save(str(trial_dir))
    mi_stats = dict(mi.stats); mi_stats["jit_s"] = mi.model.jit_s; mi.close()
    cp_stats = dict(cp.stats); cp.close(); gate_stats = gate.summary(); gate.close()
    pg_stats = None
    if pg is not None:
        pg_stats = pg.summary(); pg.close()
    manifest = {"attempt_id": attempt_id, "arm": a.arm, "phase": a.phase, "suite": a.suite, "task": a.task, "task_short": short, "seed": a.seed, "state_idx": state_idx, "n_init_states": n_states, "policy_sha256": code_sha, "policy_path": str(a.code),
                "task_language": getattr(env.low_level_env.handle, "task_language", None), "task_descriptors": descriptors, "official_task_completed": tc, "sandbox_rc": src, "reward": reward, "terminated": bool(terminated), "truncated": bool(truncated),
                "policy_duration_s": round(duration, 1), "env_setup_s": round(env_setup_s, 1), "final_sim_step": final["sim_step"], "final_official_predicates": final["official_predicates"], "final_official_full_success": final["official_full_success"],
                "stderr_tail": (info_step.get("stderr", "") or "")[-1500:], "gpu": os.environ.get("CUDA_VISIBLE_DEVICES"), "timestamp": time.strftime("%Y-%m-%dT%H:%M:%S"), "model_calls": int(install_interface.vlm_stats["calls"]), "vlm_stats": dict(install_interface.vlm_stats),
                "motion_interface_stats": mi_stats, "contact_primitive_stats": cp_stats, "gate_stats": gate_stats, "placement_gate_stats": pg_stats, "home_motion_stats": home_stats if a.arm in G_ARMS else None}
    manifest.update(adapter_revision=ADAPTER_REVISION, descriptor_sha256=descriptor_sha, adapter_files_sha256=adapter_files)
    manifest.update(harness_revision="n8_clean_horizon_v1", failure_class=info_step.get("failure_class"), horizon_exhausted=horizon_guard.exhausted)
    meta = rec.save(manifest)
    (out / "attempt_manifest.json").write_text(json.dumps({**manifest, "n_events": meta["n_events"], "n_samples": meta["n_samples"], "n_obs": meta["n_obs"], "n_marks": meta["n_marks"], "perception_calls": meta["perception_calls"], "recorder_errors": meta["errors"]}, indent=2, default=str))
    print("ATTEMPT_DONE", json.dumps({k: manifest[k] for k in ("attempt_id", "arm", "task_short", "seed", "state_idx", "official_task_completed", "sandbox_rc", "policy_duration_s", "final_sim_step")} | {"n_events": meta["n_events"], "errors": meta["errors"], "mi": mi_stats, "cp": cp_stats, "gate": gate_stats, "pg": pg_stats, "home": manifest["home_motion_stats"]}, default=str))


if __name__ == "__main__":
    main()
